// Package identitysql owns the retained identity administration statements.
// Legacy repositories and the native admitted profile compile the same bytes.
package identitysql

const (
	UpdateMemberRole          = `WITH updated AS (UPDATE zasp_identity_memberships SET role=$3,version=version+1 WHERE organization_id=$1 AND principal_id=$2 AND version=$4 AND active RETURNING *), revoked AS (UPDATE zasp_product_sessions SET revoked_at=COALESCE(revoked_at,transaction_timestamp()),version=version+1 WHERE organization_id=$1 AND principal_id=$2 AND revoked_at IS NULL AND EXISTS(SELECT 1 FROM updated)), audited AS (INSERT INTO zasp_admin_audit(organization_id,workspace_id,environment_id,id,actor_id,action,target_id,outcome,metadata) SELECT $1,$5,$6,$7,$8,'member.role.update',$2,'succeeded',jsonb_build_object('role',$3::text) FROM updated), result AS (SELECT jsonb_build_object('id',principal_id,'organization_id',organization_id,'organization_reference',organization_reference,'member_reference',member_reference,'role',role,'active',active,'version',version,'audit_correlation_id',$7::text) AS payload FROM updated) SELECT COALESCE((SELECT payload FROM result),jsonb_build_object('_mutation_state',CASE WHEN EXISTS(SELECT 1 FROM zasp_identity_memberships WHERE organization_id=$1 AND principal_id=$2) THEN 'conflict' ELSE 'not_found' END))`
	UpsertGroupMapping        = `WITH created AS (INSERT INTO zasp_group_mappings(organization_id,group_reference,role,workspace_id,environment_id,version) SELECT $1,$2,$3,$4,$5,1 WHERE $6=0 ON CONFLICT(organization_id,group_reference) DO NOTHING RETURNING *), updated AS (UPDATE zasp_group_mappings SET role=$3,workspace_id=$4,environment_id=$5,version=version+1,updated_at=transaction_timestamp() WHERE $6>0 AND organization_id=$1 AND group_reference=$2 AND version=$6 RETURNING *), changed AS (SELECT * FROM created UNION ALL SELECT * FROM updated), revoked_sessions AS (UPDATE zasp_product_sessions SET revoked_at=COALESCE(revoked_at,transaction_timestamp()),version=CASE WHEN revoked_at IS NULL THEN version+1 ELSE version END WHERE organization_id=$1 AND revoked_at IS NULL AND EXISTS(SELECT 1 FROM changed) RETURNING session_id), revoked_tokens AS (UPDATE zasp_product_api_tokens SET revoked_at=COALESCE(revoked_at,transaction_timestamp()),version=CASE WHEN revoked_at IS NULL THEN version+1 ELSE version END WHERE organization_id=$1 AND revoked_at IS NULL AND EXISTS(SELECT 1 FROM changed) RETURNING id), audited AS (INSERT INTO zasp_admin_audit(organization_id,workspace_id,environment_id,id,actor_id,action,target_id,outcome,metadata) SELECT $1,$4,$5,$7,$8,'group_mapping.update',$9,'succeeded',jsonb_build_object('group_reference',$2::text,'revoked_sessions',(SELECT count(*) FROM revoked_sessions),'revoked_tokens',(SELECT count(*) FROM revoked_tokens)) FROM changed), result AS (SELECT jsonb_build_object('group_reference',group_reference,'role',role,'workspace_id',workspace_id,'environment_id',environment_id,'version',version,'audit_correlation_id',$7::text) AS payload FROM changed) SELECT COALESCE((SELECT payload FROM result),jsonb_build_object('_mutation_state',CASE WHEN EXISTS(SELECT 1 FROM zasp_group_mappings WHERE organization_id=$1 AND group_reference=$2) THEN 'conflict' ELSE 'not_found' END))`
	CreateAPIToken            = `WITH mutex AS MATERIALIZED (SELECT pg_advisory_xact_lock(hashtextextended($1||chr(31)||$2||chr(31)||'createAPIToken'||chr(31)||$3,0))), authorized AS MATERIALIZED (SELECT 1 FROM zasp_authorized_scopes scope JOIN zasp_workspaces workspace ON workspace.organization_id=scope.organization_id AND workspace.id=scope.workspace_id JOIN zasp_environments environment ON environment.organization_id=scope.organization_id AND environment.workspace_id=scope.workspace_id AND environment.id=scope.environment_id CROSS JOIN mutex WHERE scope.principal_id=$2 AND scope.organization_id=$1 AND scope.workspace_id=$7 AND scope.environment_id=$8), previous AS MATERIALIZED (SELECT response,request_digest FROM zasp_admin_idempotency JOIN authorized ON true WHERE organization_id=$1 AND principal_id=$2 AND operation='createAPIToken' AND idempotency_key=$3), created AS (INSERT INTO zasp_product_api_tokens(token_digest,id,name,principal_id,organization_id,workspace_id,environment_id,permissions,expires_at,audit_correlation_id) SELECT $5,$6,$9,$2,$1,$7,$8,$10::jsonb,$11,$12 FROM authorized WHERE NOT EXISTS(SELECT 1 FROM previous) RETURNING *), granted AS (INSERT INTO zasp_api_token_reveal_grants(organization_id,workspace_id,environment_id,principal_id,token_id,grant_id,operation,ciphertext,nonce,authentication_tag,expires_at) SELECT $1,$7,$8,$2,$6,$13,'createAPIToken',$15,$16,$17,$14 FROM created RETURNING grant_id,expires_at), audited AS (INSERT INTO zasp_admin_audit(organization_id,workspace_id,environment_id,id,actor_id,action,target_id,outcome,metadata) SELECT $1,$7,$8,$12,$2,'api_token.create',$6,'succeeded','{}'::jsonb FROM granted), claimed AS (INSERT INTO zasp_admin_idempotency(organization_id,principal_id,operation,idempotency_key,request_digest,workspace_id,environment_id,grant_id,response) SELECT $1,$2,'createAPIToken',$3,$4,$7,$8,$13,jsonb_build_object('grant_id',$13::text,'expires_at',$14,'token',jsonb_build_object('id',created.id,'name',created.name,'principal_id',created.principal_id,'workspace_id',created.workspace_id,'environment_id',created.environment_id,'permissions',created.permissions,'created_at',created.created_at,'expires_at',created.expires_at,'last_used_at',created.last_used_at,'revoked_at',created.revoked_at,'version',created.version,'audit_correlation_id',created.audit_correlation_id)) FROM created RETURNING response) SELECT CASE WHEN EXISTS(SELECT 1 FROM previous WHERE request_digest<>$4) THEN jsonb_build_object('_mutation_state','conflict') ELSE COALESCE((SELECT response FROM previous),(SELECT response FROM claimed),jsonb_build_object('_mutation_state','not_found')) END`
	RotateAPIToken            = `WITH mutex AS MATERIALIZED (SELECT pg_advisory_xact_lock(hashtextextended($1||chr(31)||$2||chr(31)||'rotateAPIToken'||chr(31)||$3,0))), scoped AS MATERIALIZED (SELECT 1 AS authorized FROM zasp_product_api_tokens token JOIN zasp_authorized_scopes scope ON scope.principal_id=$2 AND scope.organization_id=token.organization_id AND scope.workspace_id=token.workspace_id AND scope.environment_id=token.environment_id CROSS JOIN mutex WHERE token.organization_id=$1 AND token.workspace_id=$10 AND token.environment_id=$11 AND token.id=$5), previous AS MATERIALIZED (SELECT idempotency.response,idempotency.request_digest FROM zasp_admin_idempotency idempotency JOIN scoped ON true WHERE idempotency.organization_id=$1 AND idempotency.principal_id=$2 AND idempotency.operation='rotateAPIToken' AND idempotency.idempotency_key=$3), revoked AS (UPDATE zasp_product_api_tokens SET revoked_at=transaction_timestamp(),version=version+1 WHERE organization_id=$1 AND workspace_id=$10 AND environment_id=$11 AND id=$5 AND version=$6 AND revoked_at IS NULL AND NOT EXISTS(SELECT 1 FROM previous) RETURNING *), destroyed AS (UPDATE zasp_api_token_reveal_grants SET acknowledged_at=COALESCE(acknowledged_at,transaction_timestamp()),ciphertext=NULL,nonce=NULL,authentication_tag=NULL WHERE organization_id=$1 AND token_id=$5 AND acknowledged_at IS NULL AND EXISTS(SELECT 1 FROM revoked)), created AS (INSERT INTO zasp_product_api_tokens(token_digest,id,name,principal_id,organization_id,workspace_id,environment_id,permissions,expires_at,audit_correlation_id) SELECT $7,$8,name,principal_id,organization_id,workspace_id,environment_id,permissions,expires_at,$9 FROM revoked RETURNING *), granted AS (INSERT INTO zasp_api_token_reveal_grants(organization_id,workspace_id,environment_id,principal_id,token_id,grant_id,operation,ciphertext,nonce,authentication_tag,expires_at) SELECT $1,$10,$11,$2,$8,$12,'rotateAPIToken',$14,$15,$16,$13 FROM created RETURNING grant_id), audited AS (INSERT INTO zasp_admin_audit(organization_id,workspace_id,environment_id,id,actor_id,action,target_id,outcome,metadata) SELECT $1,$10,$11,$9,$2,'api_token.rotate',$5,'succeeded',jsonb_build_object('replacement_id',$8::text) FROM granted), claimed AS (INSERT INTO zasp_admin_idempotency(organization_id,principal_id,operation,idempotency_key,request_digest,workspace_id,environment_id,grant_id,response) SELECT $1,$2,'rotateAPIToken',$3,$4,$10,$11,$12,jsonb_build_object('grant_id',$12::text,'expires_at',$13,'token',jsonb_build_object('id',created.id,'name',created.name,'principal_id',created.principal_id,'workspace_id',created.workspace_id,'environment_id',created.environment_id,'permissions',created.permissions,'created_at',created.created_at,'expires_at',created.expires_at,'last_used_at',created.last_used_at,'revoked_at',created.revoked_at,'version',created.version,'audit_correlation_id',created.audit_correlation_id)) FROM created RETURNING response) SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM scoped) THEN jsonb_build_object('_mutation_state','not_found') WHEN EXISTS(SELECT 1 FROM previous WHERE request_digest<>$4) THEN jsonb_build_object('_mutation_state','conflict') ELSE COALESCE((SELECT response FROM previous),(SELECT response FROM claimed),jsonb_build_object('_mutation_state','conflict')) END`
	RevokeAPIToken            = `WITH scoped AS MATERIALIZED (SELECT token.* FROM zasp_product_api_tokens token JOIN zasp_authorized_scopes scope ON scope.principal_id=$7 AND scope.organization_id=token.organization_id AND scope.workspace_id=token.workspace_id AND scope.environment_id=token.environment_id WHERE token.organization_id=$1 AND token.workspace_id=$2 AND token.environment_id=$3 AND token.id=$4), revoked AS (UPDATE zasp_product_api_tokens SET revoked_at=COALESCE(revoked_at,transaction_timestamp()),version=CASE WHEN revoked_at IS NULL THEN version+1 ELSE version END WHERE organization_id=$1 AND workspace_id=$2 AND environment_id=$3 AND id=$4 AND version=$5 AND EXISTS(SELECT 1 FROM scoped) RETURNING *), destroyed AS (UPDATE zasp_api_token_reveal_grants SET acknowledged_at=COALESCE(acknowledged_at,transaction_timestamp()),ciphertext=NULL,nonce=NULL,authentication_tag=NULL WHERE organization_id=$1 AND workspace_id=$2 AND environment_id=$3 AND token_id=$4 AND acknowledged_at IS NULL AND EXISTS(SELECT 1 FROM revoked)), audited AS (INSERT INTO zasp_admin_audit(organization_id,workspace_id,environment_id,id,actor_id,action,target_id,outcome,metadata) SELECT $1,workspace_id,environment_id,$6,$7,'api_token.revoke',$4,'succeeded','{}'::jsonb FROM revoked), result AS (SELECT jsonb_build_object('id',id,'name',name,'principal_id',principal_id,'workspace_id',workspace_id,'environment_id',environment_id,'permissions',permissions,'created_at',created_at,'expires_at',expires_at,'last_used_at',last_used_at,'revoked_at',revoked_at,'version',version,'audit_correlation_id',$6::text) AS payload FROM revoked) SELECT COALESCE((SELECT payload FROM result),jsonb_build_object('_mutation_state',CASE WHEN EXISTS(SELECT 1 FROM scoped) THEN 'conflict' ELSE 'not_found' END))`
	AcknowledgeAPITokenReveal = `WITH scoped AS MATERIALIZED (SELECT token_id,acknowledged_at FROM zasp_api_token_reveal_grants WHERE organization_id=$1 AND workspace_id=$2 AND environment_id=$3 AND principal_id=$4 AND grant_id=$5), acknowledged AS (UPDATE zasp_api_token_reveal_grants SET acknowledged_at=transaction_timestamp(),ciphertext=NULL,nonce=NULL,authentication_tag=NULL WHERE organization_id=$1 AND workspace_id=$2 AND environment_id=$3 AND principal_id=$4 AND grant_id=$5 AND acknowledged_at IS NULL RETURNING token_id), audited AS (INSERT INTO zasp_admin_audit(organization_id,workspace_id,environment_id,id,actor_id,action,target_id,outcome,metadata) SELECT $1,$2,$3,$6,$4,'api_token.reveal.acknowledge',token_id,'succeeded',jsonb_build_object('grant_id',$5::text) FROM acknowledged) SELECT CASE WHEN EXISTS(SELECT 1 FROM scoped) THEN jsonb_build_object('acknowledged',true) ELSE jsonb_build_object('_mutation_state','not_found') END`
	RevokeInvestigatedSession = `WITH revoked AS (UPDATE zasp_product_sessions SET revoked_at=COALESCE(revoked_at,transaction_timestamp()),version=CASE WHEN revoked_at IS NULL THEN version+1 ELSE version END WHERE organization_id=$1 AND workspace_id=$2 AND environment_id=$3 AND session_id=$4 AND version=$5 RETURNING *), audited AS (INSERT INTO zasp_admin_audit(organization_id,workspace_id,environment_id,id,actor_id,action,target_id,outcome,metadata) SELECT $1,$2,$3,$6,$7,'session.revoke',$8,'succeeded',jsonb_build_object('session_id',$4::text) FROM revoked), result AS (SELECT jsonb_build_object('version',version) AS payload FROM revoked) SELECT COALESCE((SELECT payload FROM result),jsonb_build_object('_mutation_state',CASE WHEN EXISTS(SELECT 1 FROM zasp_product_sessions WHERE organization_id=$1 AND workspace_id=$2 AND environment_id=$3 AND session_id=$4) THEN 'conflict' ELSE 'not_found' END))`
	ListAPITokens             = `SELECT jsonb_build_object('items', COALESCE(jsonb_agg(item ORDER BY item->>'id'), '[]'::jsonb)) FROM (SELECT jsonb_build_object('id', id, 'name', name, 'principal_id', principal_id, 'workspace_id', workspace_id, 'environment_id', environment_id, 'permissions', permissions, 'created_at', created_at, 'expires_at', expires_at, 'last_used_at', last_used_at, 'revoked_at', revoked_at, 'version', version, 'audit_correlation_id', audit_correlation_id) AS item FROM zasp_product_api_tokens WHERE organization_id=$1 AND workspace_id=$2 AND environment_id=$3 AND ($4='' OR id>$4) ORDER BY id LIMIT $5) AS page`
	ListAPITokenRevealGrants  = `WITH cleaned AS (UPDATE zasp_api_token_reveal_grants reveal SET acknowledged_at=COALESCE(reveal.acknowledged_at,transaction_timestamp()),ciphertext=NULL,nonce=NULL,authentication_tag=NULL FROM zasp_product_api_tokens token WHERE reveal.organization_id=$1 AND reveal.workspace_id=$2 AND reveal.environment_id=$3 AND reveal.principal_id=$4 AND reveal.token_id=token.id AND token.organization_id=reveal.organization_id AND reveal.acknowledged_at IS NULL AND (reveal.expires_at<=transaction_timestamp() OR token.revoked_at IS NOT NULL OR token.expires_at<=transaction_timestamp())) SELECT jsonb_build_object('items',COALESCE(jsonb_agg(jsonb_build_object('grant_id',grant_id,'token_id',token_id,'operation',operation,'expires_at',expires_at) ORDER BY grant_id),'[]'::jsonb)) FROM (SELECT grant_id,token_id,operation,expires_at FROM zasp_api_token_reveal_grants WHERE organization_id=$1 AND workspace_id=$2 AND environment_id=$3 AND principal_id=$4 AND acknowledged_at IS NULL AND expires_at>transaction_timestamp() AND ($5='' OR grant_id>$5) ORDER BY grant_id LIMIT $6) pending`
	RevealAPIToken            = `SELECT jsonb_build_object('grant_id',reveal.grant_id,'token_id',reveal.token_id,'operation',reveal.operation,'expires_at',reveal.expires_at,'ciphertext',translate(rtrim(encode(reveal.ciphertext,'base64'),'='),'+/','-_'),'nonce',translate(rtrim(encode(reveal.nonce,'base64'),'='),'+/','-_'),'authentication_tag',translate(rtrim(encode(reveal.authentication_tag,'base64'),'='),'+/','-_')) FROM zasp_api_token_reveal_grants reveal JOIN zasp_product_api_tokens token ON token.organization_id=reveal.organization_id AND token.id=reveal.token_id WHERE reveal.organization_id=$1 AND reveal.workspace_id=$2 AND reveal.environment_id=$3 AND reveal.principal_id=$4 AND reveal.grant_id=$5 AND reveal.acknowledged_at IS NULL AND reveal.expires_at>transaction_timestamp() AND token.workspace_id=$2 AND token.environment_id=$3 AND token.revoked_at IS NULL AND token.expires_at>transaction_timestamp()`
)
